struct node {
    int elem;
    struct node next;     // a whole node inside a node?
};

int main(void) {
    return 0;
}

#include <stdio.h>

struct node {
    int elem;
    struct node *next;
};

int main(void) {
    struct node n1;
    struct node n2;
    struct node n3;

    // n1 is the start of the sequence
    n1.elem = 1;
    n1.next = &n2;

    n2.elem = 2;
    n2.next = &n3;

    // n3 is the end of the sequence so its next member is NULL
    n3.elem = 3;
    n3.next = NULL;

    printf("n1.elem             = %d\n", n1.elem);
    printf("n1.next->elem       = %d\n", n1.next->elem);
    printf("n1.next->next->elem = %d\n", n1.next->next->elem);
    if (n3.next == NULL) {
        printf("n3.next is NULL\n");
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node {
    int elem;
    struct node *next;
};

int main(void) {
    struct node *n1 = malloc(sizeof(struct node));
    struct node *n2 = malloc(sizeof(struct node));
    struct node *n3 = malloc(sizeof(struct node));
    if (!n1 || !n2 || !n3) {
        fprintf(stderr, "out of memory\n");
        free(n1);
        free(n2);
        free(n3);
        exit(EXIT_FAILURE);
    }

    // n1 is the start of the sequence
    n1->elem = 1;
    n1->next = n2;

    n2->elem = 2;
    n2->next = n3;

    // n3 is the end of the sequence so its next member is NULL
    n3->elem = 3;
    n3->next = NULL;

    // follow the links from the first node
    for (struct node *p = n1; p != NULL; p = p->next) {
        printf("%d\n", p->elem);
    }

    free(n1);
    free(n2);
    free(n3);
    return 0;
}

