#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

struct node {
    int elem;
    struct node *next;
};

struct qlstack_tag {
    struct node *top;
    size_t size;
};

typedef struct qlstack_tag qlstack;

qlstack *qlstack_new(void) {
    qlstack *s = malloc(sizeof(qlstack));
    if (!s) {
        return NULL;
    }
    s->top = NULL;
    s->size = 0;
    return s;
}

bool qlstack_is_empty(const qlstack *s) {
    return s->size == 0;
}

size_t qlstack_size(const qlstack *s) {
    return s->size;
}

qlstack *qlstack_push(qlstack *s, int elem) {
    if (!s) {
        return NULL;
    }
    struct node *n = malloc(sizeof(struct node));
    if (!n) {
        return NULL;
    }
    n->elem = elem;
    n->next = s->top;
    s->top = n;
    s->size++;
    return s;
}

int main(void) {
    qlstack *s = qlstack_new();
    if (!s) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    printf("empty? %d, size %zu\n", qlstack_is_empty(s), qlstack_size(s));

    for (int i = 1; i <= 3; i++) {
        if (!qlstack_push(s, i)) {
            fprintf(stderr, "out of memory\n");
            exit(EXIT_FAILURE);
        }
        printf("pushed %d: top elem %d, size %zu\n", i, s->top->elem, qlstack_size(s));
    }
    printf("empty? %d\n", qlstack_is_empty(s));

    printf("top to bottom:");
    for (struct node *n = s->top; n != NULL; n = n->next) {
        printf(" %d", n->elem);
    }
    printf("\n");
    // the nodes and the stack are not freed yet: Day 24 writes qlstack_free
    return 0;
}

