// BROKEN: the last two link steps are in the wrong order
qlstack *bad_push(qlstack *s, int elem) {
    struct node *n = malloc(sizeof(struct node));
    if (!n) {
        return NULL;
    }
    n->elem = elem;
    s->top = n;          // top now points at the new node...
    n->next = s->top;    // ...so this makes the new node point at ITSELF
    s->size++;
    return s;
}

int main(void) {
    qlstack st = { NULL, 0 };     // a stack struct on the stack, for this test only
    bad_push(&st, 1);
    bad_push(&st, 2);
    printf("size %zu, top elem %d\n", st.size, st.top->elem);
    if (st.top->next == st.top) {
        printf("the top node's next points at the top node itself\n");
    }
    printf("following next 5 times:");
    struct node *p = st.top;
    for (int i = 0; i < 5; i++) {
        printf(" %d", p->elem);
        p = p->next;
    }
    printf("\n");
    return 0;
}

