#include <stdio.h>
#include <stdlib.h>

struct node {
    int elem;
    struct node *next;
};

// Makes a new node holding elem in front of the node first points at
// (first may be NULL for an empty list). Returns a pointer to the new
// first node, or NULL if memory runs out.
struct node *prepend(struct node *first, int elem) {
    struct node *n = malloc(sizeof(struct node));
    if (!n) {
        return NULL;
    }
    n->elem = elem;
    n->next = first;
    return n;
}

int main(void) {
    struct node *list = NULL;          // an empty list
    for (int v = 30; v >= 10; v = v - 10) {
        list = prepend(list, v);
        if (!list) {
            fprintf(stderr, "out of memory\n");
            exit(EXIT_FAILURE);
        }
    }
    for (struct node *p = list; p != NULL; p = p->next) {
        printf("%d ", p->elem);
    }
    printf("\n");
    return 0;
}

