#include <stdio.h>
#include <stdlib.h>

struct dnode {
    double val;
    struct dnode *below;
};

struct dstack {
    struct dnode *top;
    size_t count;
};

// Returns a pointer to a new empty stack, or NULL if memory runs out.
struct dstack *dstack_new(void) {
    struct dstack *s = malloc(sizeof(struct dstack));
    if (!s) {
        return NULL;
    }
    s->top = NULL;
    s->count = 0;
    return s;
}

// Pushes val onto the top of the stack s points at.
// Returns s, or NULL if s is NULL or memory runs out.
struct dstack *dstack_push(struct dstack *s, double val) {
    if (!s) {
        return NULL;
    }
    struct dnode *n = malloc(sizeof(struct dnode));
    if (!n) {
        return NULL;
    }
    n->val = val;
    n->below = s->top;
    s->top = n;
    s->count++;
    return s;
}

int main(void) {
    struct dstack *s = dstack_new();
    if (!dstack_push(s, 1.5) || !dstack_push(s, 2.5) || !dstack_push(s, 4.0)) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    for (struct dnode *n = s->top; n != NULL; n = n->below) {
        printf("%.1f ", n->val);
    }
    printf("\ncount %zu\n", s->count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Cell {
    int value;            // the data in this node
    struct Cell *next;    // pointer to the next node
};

typedef struct Cell *CellList;   // a list is a pointer to its first node

int insertSecond(CellList list, int value) {
    if (list == NULL) {
        return 0;                       // empty list: nothing to insert after
    }
    struct Cell *n = malloc(sizeof(struct Cell));
    if (!n) {
        return 0;                       // out of memory: change nothing
    }
    n->value = value;
    n->next = list->next;               // 1. new node points at the old second node
    list->next = n;                     // 2. first node points at the new node
    return 1;
}

void printList(CellList list) {
    printf("[");
    for (struct Cell *p = list; p != NULL; p = p->next) {
        printf("%d", p->value);
        if (p->next != NULL) {
            printf(",");
        }
    }
    printf("]\n");
}

int main(void) {
    CellList list = NULL;
    printf("on empty: %d ", insertSecond(list, 5));
    printList(list);

    struct Cell *one = malloc(sizeof(struct Cell));
    if (!one) {
        return 1;
    }
    one->value = 7;
    one->next = NULL;
    printf("returned %d ", insertSecond(one, 8));
    printList(one);

    struct Cell *last = malloc(sizeof(struct Cell));
    struct Cell *first = malloc(sizeof(struct Cell));
    if (!last || !first) {
        return 1;
    }
    last->value = 30;
    last->next = NULL;
    first->value = 10;
    first->next = last;
    list = first;
    printList(list);
    printf("returned %d ", insertSecond(list, 20));
    printList(list);
    printf("returned %d ", insertSecond(list, 15));
    printList(list);

    return 0;
}
